<?php
namespace App\Http\Requests\PublicChrome;
use App\Domain\PublicChrome\PublicAssetPath; use Illuminate\Foundation\Http\FormRequest; use Illuminate\Validation\Validator;
class BrandingRequest extends FormRequest { public function authorize():bool{return true;} protected function prepareForValidation():void{$this->merge(['show_product_attribution'=>$this->boolean('show_product_attribution')]);} public function rules():array{return ['site_logo_path'=>['nullable','string','max:255'], 'site_logo_dark_path'=>['nullable','string','max:255'],'favicon_path'=>['nullable','string','max:255'],'logo_alt_text'=>['nullable','string','max:160'],'brand_mark_text'=>['nullable','string','max:12'],'primary_color'=>['nullable','regex:/^#[0-9A-Fa-f]{6}$/'],'secondary_color'=>['nullable','regex:/^#[0-9A-Fa-f]{6}$/'],'accent_color'=>['nullable','regex:/^#[0-9A-Fa-f]{6}$/'],'show_product_attribution'=>['boolean']];} public function after():array{return [function(Validator $v){foreach(['site_logo_path','site_logo_dark_path'] as $field){if(!PublicAssetPath::isSafe($this->input($field)))$v->errors()->add($field,'Use a safe local images, assets, or storage path.');}if(!PublicAssetPath::isSafe($this->input('favicon_path'),true))$v->errors()->add('favicon_path','Use a supported local favicon path.');if(($this->filled('site_logo_path')||$this->filled('site_logo_dark_path'))&&!$this->filled('logo_alt_text'))$v->errors()->add('logo_alt_text','Alt text is required when a logo is configured.');}];} }
